language "moriarty-sherlock-draft/1";
program P {
  fn fact(n: UInt): UInt { if n == 0 { 1 } else { n * fact(n - 1) } }
  entry fact(3);
}

language "moriarty-sherlock-draft/1";
program P {
  fn even(n: UInt): Bool { if n == 0 { true } else { odd(n - 1) } }
  fn odd(n: UInt): Bool { if n == 0 { false } else { even(n - 1) } }
  entry even(4);
}

